import { get, handleApiError } from '@helpers/httpClient';

export interface IUser {
  id: number;
  name: string;
  surname: string;
  photo: string;
}

interface IUserDto {
  id: string;
  name: string;
  surname: string;
  photo: string;
}

export const getAllUsers = async (): Promise<IUser[]> => {
  const res = await get<IUserDto[]>('/ajax/users/list.php').then(handleApiError);
  return res.map((u: IUserDto) => {
    return {
      ...u,
      id: +u.id,
    } as IUser;
  });
};
