import React from 'react';

import { getAllUsers, IUser } from '@apps/Users/@services/users.service';
import { err } from '@helpers/notificationHelper';
import PohAva from '@ui-kit/Ava';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohList from '@ui-kit/List';

import PageLoader from '../PageLoader';

interface IUserSelectorProps {
  onSelect: (selectedHiker: IUser) => void;
  excludeIds?: number[];
}

const UserSelector: React.FC<IUserSelectorProps> = ({ excludeIds, onSelect }) => {
  const [users, setUsers] = React.useState<IUser[]>([]);
  const [q, setQ] = React.useState<string>('');
  const [isLoading, setIsLoading] = React.useState(false);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const usersData = await getAllUsers();

        setUsers(usersData);
      } finally {
        setIsLoading(false);
      }
    };

    init().catch(err);
  }, []);

  if (isLoading) {
    return <PageLoader />;
  }

  return (
    <div style={{ minWidth: 320 }} className="mt-n2">
      <PohInput type={InputTypes.search} placeholder="Найти" onChange={setQ} value={q} autoFocus />
      <div style={{ overflowY: 'auto', maxHeight: 400 }} className="mt-1">
        <PohList
          data={users
            .filter(
              (u) =>
                !q.length || (u.name + u.surname).toLocaleLowerCase().includes(q.toLowerCase()),
            )
            .map((user) => ({
              key: user.id,
              content: (
                <>
                  <PohAva src={user.photo} alt={user.name} className="my-n2 ms-n2 me-2" />
                  <strong>
                    {user.name} {user.surname}
                  </strong>
                </>
              ),
              action: true,
              disabled: excludeIds?.includes(user.id),
              onClick: () => onSelect(user),
            }))}
        />
      </div>
    </div>
  );
};

export default UserSelector;
