import React from 'react';

import { IUser } from '@apps/Users/@services/users.service';
import { showModal } from '@ui-kit/Modal';

import UserSelector from './index';

export function selectUserAsync(options: { excludeIds?: number[] } = {}): Promise<IUser> {
  return new Promise((resolve) => {
    showModal({
      size: 'sm',
      title: 'Выбор участника',
      children: (closeHandler: () => void) => (
        <UserSelector
          excludeIds={options.excludeIds}
          onSelect={(user) => {
            resolve(user);
            closeHandler();
          }}
        />
      ),
    });
  });
}
